import React, { useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import './ProjectDetail.css'; // Reusing styles for consistency

const ProductOverview = () => {
  const { productId } = useParams();

  // Mock Database for Products
  const productsDB = {
    'indoor-monitor': {
      name: "Indoor Air Quality Monitor",
      tagline: "Know what you breathe inside.",
      image: "/sensor_modules/aqicrop.jpeg",
      features: ["PM2.5 Sensor", "CO2 Tracking", "Temperature & Humidity", "WiFi Connected"],
      desc: "A compact device designed for homes and offices to track indoor pollutants in real-time.",
      specs: { Range: "0-999 ug/m3", Power: "5V USB-C", Connectivity: "WiFi / LoRa" }
    },
    'outdoor-station': {
      name: "Outdoor Environmental Station",
      tagline: "City-wide pollution tracking.",
      image: "/sensor_modules/aqi1.jpeg",
      features: ["Solar Powered", "Weatherproof (IP67)", "Multi-Gas Sensors", "Long Range LoRa"],
      desc: " rugged outdoor station capable of withstanding harsh weather while providing accurate environmental data.",
      specs: { Range: "15km LoRa", Power: "Solar + Battery", Connectivity: "LoRaWAN" }
    },
    // Default fallback
    'default': {
      name: "Smart IoT Device",
      tagline: "Next-gen sensing technology.",
      image: "https://images.unsplash.com/photo-1518770660439-4636190af475?w=800",
      features: ["Real-time Data", "Cloud Dashboard", "Mobile App", "Easy Setup"],
      desc: "High-precision hardware designed for the specific needs of our projects.",
      specs: { Type: "Sensor Node", Power: "Battery/Mains", Connectivity: "Wireless" }
    }
  };

  const product = productsDB[productId] || productsDB['default'];

  useEffect(() => { window.scrollTo(0, 0); }, [productId]);

  return (
    <div className="project-page">
      {/* Simple Header */}
      <header className="aiiot-header-local">
         <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1.5rem', display:'flex', justifyContent:'space-between', alignItems:'center', height:'5rem' }}>
            <Link to="/" style={{textDecoration:'none', color:'#1e293b', fontWeight:'800', fontSize:'1.2rem'}}>AI-IoT Innovations</Link>
            <Link to="/products" style={{textDecoration:'none', color:'#3b82f6', fontWeight:'600'}}>← Back to Products</Link>
         </div>
      </header>

      <div className="container" style={{paddingTop: '8rem', paddingBottom: '5rem'}}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4rem', alignItems: 'center' }}>
          
          {/* Text Side */}
          <div>
            <span style={{background:'#dbeafe', color:'#1e40af', padding:'0.4rem 1rem', borderRadius:'2rem', fontSize:'0.8rem', fontWeight:'bold'}}>Hardware Product</span>
            <h1 style={{fontSize:'3rem', fontWeight:'800', color:'#1e293b', marginTop:'1rem', marginBottom:'1rem'}}>{product.name}</h1>
            <p style={{fontSize:'1.25rem', color:'#64748b', marginBottom:'2rem'}}>{product.tagline}</p>
            <p style={{fontSize:'1rem', color:'#475569', lineHeight:'1.7', marginBottom:'2rem'}}>{product.desc}</p>
            
            <h3 style={{fontSize:'1.2rem', fontWeight:'700', marginBottom:'1rem'}}>Key Features:</h3>
            <ul style={{listStyle:'none', padding:0, display:'grid', gridTemplateColumns:'1fr 1fr', gap:'1rem'}}>
              {product.features.map((f, i) => (
                <li key={i} style={{display:'flex', alignItems:'center', gap:'0.5rem', color:'#334155'}}>
                  <span style={{color:'#3b82f6'}}>✓</span> {f}
                </li>
              ))}
            </ul>
            
            <div style={{marginTop:'3rem'}}>
               <button className="btn-primary">Request Quote</button>
            </div>
          </div>

          {/* Image Side */}
          <div style={{background:'white', padding:'2rem', borderRadius:'2rem', boxShadow:'0 20px 40px rgba(0,0,0,0.1)'}}>
             <img src={product.image} alt={product.name} style={{width:'100%', borderRadius:'1rem'}} />
          </div>

        </div>

        {/* Specs Table */}
        <div style={{marginTop:'5rem'}}>
           <h2 style={{textAlign:'center', marginBottom:'2rem'}}>Technical Specifications</h2>
           <div style={{maxWidth:'600px', margin:'0 auto', border:'1px solid #e2e8f0', borderRadius:'1rem', overflow:'hidden'}}>
              {Object.entries(product.specs).map(([key, val], idx) => (
                 <div key={key} style={{display:'flex', justifyContent:'space-between', padding:'1rem 2rem', background: idx%2===0 ? '#f8fafc' : 'white', borderBottom:'1px solid #f1f5f9'}}>
                    <span style={{fontWeight:'600', color:'#475569'}}>{key}</span>
                    <span style={{color:'#1e293b'}}>{val}</span>
                 </div>
              ))}
           </div>
        </div>

      </div>
    </div>
  );
};

export default ProductOverview;
